UPDATE fair_dates
   SET reserved_count = reserved_count + 1
     , updated_at = NOW()
 WHERE fair_id = #{fairId}
   AND operation_date = #{visitDate}
   AND reserved_count < capacity

UPDATE fair_dates
   SET reserved_count = reserved_count - 1
     , updated_at = NOW()
 WHERE fair_id = #{fairId}
   AND operation_date = #{visitDate}
   AND reserved_count > 0
